 async function handleManualTimesheetQueueDelete(env, req, queueId) {
  const enc = encodeURIComponent;

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  if (!queueId) {
    return withCORS(env, req, badRequest('queue_id is required'));
  }

  try {
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/manual_timesheet_queue` +
      `?id=eq.${enc(queueId)}` +
      `&select=id,status,timesheet_id,r2_key,original_filename` +
      `&limit=1`
    );
    const item = rows?.[0] || null;
    if (!item) {
      return withCORS(env, req, notFound('Queue item not found'));
    }

    const status = String(item.status || '').toUpperCase();
    if (status === 'ATTACHED') {
      return withCORS(env, req, badRequest('Cannot delete: item is already attached to a timesheet'));
    }

    const patchRes = await fetch(
      `${env.SUPABASE_URL}/rest/v1/manual_timesheet_queue?id=eq.${enc(queueId)}`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
        body: JSON.stringify({ status: 'DISCARDED' })
      }
    );

    if (!patchRes.ok) {
      const txt = await patchRes.text().catch(() => '');
      return withCORS(env, req, serverError(`Failed to discard queue item: ${txt}`));
    }

    try {
      await writeAudit(
        env,
        user,
        'MANUAL_TIMESHEET_QUEUE_DISCARDED',
        {
          queue_id: item.id,
          r2_key: item.r2_key,
          original_filename: item.original_filename
        },
        { entity: 'manual_timesheet_queue', subject_id: item.id, req }
      );
    } catch {
      // best-effort
    }

    return withCORS(env, req, ok({ discarded: true, id: item.id }));
  } catch (e) {
    console.error('[MT_QUEUE_DELETE] error', {
      queue_id: queueId,
      err: e?.message || String(e)
    });
    return withCORS(env, req, serverError('Failed to discard manual timesheet queue item'));
  }
}
 async function handleManualTimesheetQueueAttach(env, req, queueId) {
  const enc = encodeURIComponent;

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  if (!queueId) {
    return withCORS(env, req, badRequest('queue_id is required'));
  }

  let body;
  try {
    body = await parseJSONBody(req);
  } catch {
    return withCORS(env, req, badRequest('Invalid JSON'));
  }

  const timesheetId = String(body?.timesheet_id || '').trim();
  if (!timesheetId) {
    return withCORS(env, req, badRequest('timesheet_id is required'));
  }

  try {
    // Load the queue item
    const { rows: qRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/manual_timesheet_queue` +
      `?id=eq.${enc(queueId)}` +
      `&select=id,status,timesheet_id,content_hash,r2_key,last_rotation_deg,meta_json` +
      `&limit=1`
    );
    const item = qRows?.[0] || null;
    if (!item) {
      return withCORS(env, req, notFound('Queue item not found'));
    }

    const status = String(item.status || '').toUpperCase();
    if (status === 'ATTACHED') {
      if (String(item.timesheet_id || '') === timesheetId) {
        return withCORS(env, req, ok({ attached: true, id: item.id, timesheet_id: timesheetId }));
      }
      return withCORS(env, req, badRequest('Queue item already attached to a different timesheet'));
    }
    if (status === 'DISCARDED') {
      return withCORS(env, req, badRequest('Cannot attach a discarded queue item'));
    }

    // Validate timesheet exists
    const ts = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?timesheet_id=eq.${enc(timesheetId)}&select=timesheet_id&limit=1`
    );
    if (!ts) {
      return withCORS(env, req, badRequest('Timesheet not found for timesheet_id'));
    }

    // 1) Patch queue row: mark as ATTACHED + set timesheet_id
    const patchQueueRes = await fetch(
      `${env.SUPABASE_URL}/rest/v1/manual_timesheet_queue?id=eq.${enc(queueId)}`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
        body: JSON.stringify({
          status: 'ATTACHED',
          timesheet_id: timesheetId
        })
      }
    );

    if (!patchQueueRes.ok) {
      const txt = await patchQueueRes.text().catch(() => '');
      return withCORS(env, req, serverError(`Failed to attach queue item: ${txt}`));
    }

    // 2) Patch timesheet to use this PDF as manual source
    if (item.r2_key) {
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(timesheetId)}&is_current=eq.true`,
        {
          method: 'PATCH',
          headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
          body: JSON.stringify({
            manual_pdf_r2_key: item.r2_key
            // We *could* also persist last_rotation_deg onto the TS later
          })
        }
      ).catch(() => {});
    }

    // Optional audit
    try {
      await writeAudit(
        env,
        user,
        'MANUAL_TIMESHEET_QUEUE_ATTACHED',
        {
          queue_id: item.id,
          timesheet_id: timesheetId,
          content_hash: item.content_hash || null,
          r2_key: item.r2_key || null
        },
        { entity: 'manual_timesheet_queue', subject_id: item.id, req }
      );
    } catch {
      // best-effort
    }

    return withCORS(env, req, ok({ attached: true, id: item.id, timesheet_id: timesheetId }));
  } catch (e) {
    console.error('[MT_QUEUE_ATTACH] error', {
      queue_id: queueId,
      err: e?.message || String(e)
    });
    return withCORS(env, req, serverError('Failed to attach manual timesheet queue item'));
  }
}
 async function handleManualTimesheetQueueRotate(env, req, queueId) {
  const enc = encodeURIComponent;

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  if (!queueId) {
    return withCORS(env, req, badRequest('queue_id is required'));
  }

  let body;
  try {
    body = await parseJSONBody(req);
  } catch {
    return withCORS(env, req, badRequest('Invalid JSON'));
  }

  const rawRot = body?.rotation_degrees;
  if (rawRot == null) {
    return withCORS(env, req, badRequest('rotation_degrees is required'));
  }

  const normaliseRotation = (raw) => {
    let n = Number(raw);
    if (!Number.isFinite(n)) return 0;
    n = ((n % 360) + 360) % 360;
    if (n >= 315 || n < 45) return 0;
    if (n >= 45 && n < 135) return 90;
    if (n >= 135 && n < 225) return 180;
    return 270;
  };

  const deg = normaliseRotation(rawRot);

  try {
    // Ensure queue item exists
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/manual_timesheet_queue` +
      `?id=eq.${enc(queueId)}` +
      `&select=id,last_rotation_deg` +
      `&limit=1`
    );
    const item = rows?.[0] || null;
    if (!item) {
      return withCORS(env, req, notFound('Queue item not found'));
    }

    const patchRes = await fetch(
      `${env.SUPABASE_URL}/rest/v1/manual_timesheet_queue?id=eq.${enc(queueId)}`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return=representation' },
        body: JSON.stringify({ last_rotation_deg: deg })
      }
    );

    if (!patchRes.ok) {
      const txt = await patchRes.text().catch(() => '');
      return withCORS(env, req, serverError(`Failed to update rotation: ${txt}`));
    }

    const updated = (await patchRes.json().catch(() => []))[0] || { id: queueId, last_rotation_deg: deg };

    try {
      await writeAudit(
        env,
        user,
        'MANUAL_TIMESHEET_QUEUE_ROTATED',
        {
          queue_id: updated.id,
          last_rotation_deg: updated.last_rotation_deg
        },
        { entity: 'manual_timesheet_queue', subject_id: updated.id, req }
      );
    } catch {
      // best-effort
    }

    return withCORS(env, req, ok({
      id: updated.id,
      last_rotation_deg: updated.last_rotation_deg
    }));
  } catch (e) {
    console.error('[MT_QUEUE_ROTATE] error', {
      queue_id: queueId,
      err: e?.message || String(e)
    });
    return withCORS(env, req, serverError('Failed to update manual timesheet queue rotation'));
  }
}

 async function handleTimesheetPdf(env, req, timesheetId) {
  const enc = encodeURIComponent;

  // Admin auth
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  if (!timesheetId) {
    return withCORS(env, req, badRequest('timesheet_id is required'));
  }

  try {
    // ensureTimesheetPdf will either:
    // - render the TS to PDF and store in R2, or
    // - reuse an existing manual/uploaded PDF
    // It should return the R2 key (string).
    const r2Key = await ensureTimesheetPdf(env, timesheetId);
    if (!r2Key) {
      return withCORS(env, req, serverError('Failed to ensure timesheet PDF'));
    }

    // Load rotation from timesheet if available
    let rotationDeg = 0;
    try {
      const { rows: tsRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?timesheet_id=eq.${enc(timesheetId)}` +
        `&select=manual_pdf_rotation_degrees` +
        `&limit=1`
      );
      const ts = tsRows?.[0] || null;
      if (ts && ts.manual_pdf_rotation_degrees != null) {
        const n = Number(ts.manual_pdf_rotation_degrees);
        if (Number.isFinite(n)) rotationDeg = n;
      }
    } catch {
      rotationDeg = 0;
    }

    // Frontend will use r2_key + rotation_degrees to render correctly
    return withCORS(env, req, ok({
      timesheet_id: timesheetId,
      r2_key: r2Key,
      rotation_degrees: rotationDeg
    }));
  } catch (e) {
    console.error('[TIMESHEET_PDF] error', {
      timesheet_id: timesheetId,
      err: e?.message || String(e)
    });
    return withCORS(env, req, serverError('Failed to generate or locate timesheet PDF'));
  }
}

 async function handleTimesheetDailyManualUpsert(env, req, timesheetId) {
  const enc = encodeURIComponent;

  // 1) Auth
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  if (!timesheetId) {
    return withCORS(env, req, badRequest('timesheet_id is required'));
  }

  // 2) Parse body
  let body;
  try {
    body = await parseJSONBody(req);
  } catch {
    return withCORS(env, req, badRequest('Invalid JSON'));
  }

  const worked_start_iso = body?.worked_start_iso || null;
  const worked_end_iso   = body?.worked_end_iso   || null;
  const break_start_iso  = body?.break_start_iso  ?? null;
  const break_end_iso    = body?.break_end_iso    ?? null;
  const break_minutes    = (body?.break_minutes   !== undefined)
    ? body.break_minutes
    : null;

  const revokeQr  = body?.revoke_qr  === true;
  const reissueQr = body?.reissue_qr === true;

  const now = nowIso();

  // 3) Load DAILY timesheet (current version)
  const ts = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?timesheet_id=eq.${enc(timesheetId)}` +
      `&is_current=eq.true` +
      `&select=*`
  );
  if (!ts) {
    return withCORS(env, req, notFound('Timesheet not found'));
  }

  const sheetScope = String(ts.sheet_scope || '').toUpperCase();
  const subMode    = String(ts.submission_mode || '').toUpperCase();

  if (sheetScope !== 'DAILY') {
    return withCORS(
      env,
      req,
      badRequest('Timesheet is not DAILY; daily-manual-upsert only applies to DAILY sheets')
    );
  }

  if (subMode !== 'MANUAL') {
    return withCORS(
      env,
      req,
      badRequest('Timesheet must be MANUAL before editing hours. Use switch-daily-to-manual first.')
    );
  }

  // 4) Load TSFIN – must not be locked/paid
  const tsfin = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
      `?timesheet_id=eq.${enc(timesheetId)}` +
      `&is_current=eq.true` +
      `&select=*`
  ).catch(() => null);

  if (tsfin && (tsfin.locked_by_invoice_id || tsfin.paid_at_utc)) {
    return withCORS(
      env,
      req,
      badRequest('Timesheet already invoiced or paid; cannot edit DAILY manual hours')
    );
  }

  const hadQrBefore = !!ts.qr_status;

  // 5) Patch timesheet worked/break fields
  const tsPatch = {
    updated_at: now
  };

  // Only override fields that are explicitly provided; otherwise keep existing
  if (worked_start_iso !== null) tsPatch.worked_start_iso = worked_start_iso;
  if (worked_end_iso   !== null) tsPatch.worked_end_iso   = worked_end_iso;
  if (break_start_iso  !== null) tsPatch.break_start_iso  = break_start_iso;
  if (break_end_iso    !== null) tsPatch.break_end_iso    = break_end_iso;
  if (break_minutes    !== null) tsPatch.break_minutes    = break_minutes;

  try {
    await fetch(
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?timesheet_id=eq.${enc(timesheetId)}&is_current=eq.true`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
        body: JSON.stringify(tsPatch)
      }
    );
  } catch (e) {
    return withCORS(
      env,
      req,
      serverError(`Failed to update daily timesheet hours: ${e?.message || e}`)
    );
  }

  // 6) Reload updated timesheet for snapshot + QR
  const updatedTs = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?timesheet_id=eq.${enc(timesheetId)}` +
      `&is_current=eq.true` +
      `&select=*`
  );

  // 7) Rebuild DAILY snapshot (TSFIN)
  try {
    await buildDailySnapshot(env, updatedTs);
  } catch (e) {
    console.warn('[TS_DAILY_MANUAL][SNAPSHOT] buildDailySnapshot failed', e?.message || e);
    return withCORS(
      env,
      req,
      serverError(`Failed to recompute daily snapshot: ${e?.message || e}`)
    );
  }

  // Reload TSFIN after recompute
  const finAfter = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
      `?timesheet_id=eq.${enc(timesheetId)}` +
      `&is_current=eq.true` +
      `&select=*`
  ).catch(() => null);

  // 8) QR revoke (if requested)
  let qrRevoked  = false;
  let qrReissued = false;
  let pdfKey     = null;

  if (revokeQr && hadQrBefore && finAfter && !finAfter.locked_by_invoice_id && !finAfter.paid_at_utc) {
    const qrClearPatch = {
      qr_token: null,
      qr_status: null,
      qr_payload_json: null,
      qr_generated_at: null,
      qr_r2_key: null,
      qr_scan_info_json: null,
      updated_at: nowIso()
    };

    try {
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/timesheets` +
          `?timesheet_id=eq.${enc(timesheetId)}&is_current=eq.true`,
        {
          method: 'PATCH',
          headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
          body: JSON.stringify(qrClearPatch)
        }
      );
      qrRevoked = true;
    } catch (e) {
      console.warn('[TS_DAILY_MANUAL][QR] revoke patch failed', e?.message || e);
      return withCORS(
        env,
        req,
        serverError('Failed to revoke existing daily QR timesheet')
      );
    }
  }

  // 9) QR reissue (if requested AND there was a QR before)
  if (reissueQr && hadQrBefore && finAfter && !finAfter.locked_by_invoice_id && !finAfter.paid_at_utc) {
    const now2 = nowIso();

    // 9a) Ensure TSFIN is AWAITING_MANUAL_SIGNATURE for the QR flow
    if (String(finAfter.processing_status || '').toUpperCase() !== 'AWAITING_MANUAL_SIGNATURE') {
      try {
        await fetch(
          `${env.SUPABASE_URL}/rest/v1/timesheets_financials?id=eq.${enc(finAfter.id)}`,
          {
            method: 'PATCH',
            headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
            body: JSON.stringify({
              processing_status: 'AWAITING_MANUAL_SIGNATURE',
              updated_at: now2
            })
          }
        );
      } catch (e) {
        console.warn('[TS_DAILY_MANUAL][QR] failed to patch TSFIN to AWAITING_MANUAL_SIGNATURE', {
          timesheet_id: timesheetId,
          err: e?.message || String(e)
        });
        return withCORS(
          env,
          req,
          serverError('Failed to set TSFIN to AWAITING_MANUAL_SIGNATURE for QR reissue')
        );
      }
    }

    // 9b) Derive worked_date (YMD) from worked_start_iso
    let workedDateYmd = null;
    if (updatedTs.worked_start_iso) {
      try {
        const parts = toLocalParts(updatedTs.worked_start_iso, null);
        workedDateYmd = parts && parts.ymd ? parts.ymd : String(updatedTs.worked_start_iso).slice(0, 10);
      } catch {
        workedDateYmd = String(updatedTs.worked_start_iso).slice(0, 10);
      }
    }

    // 9c) Generate new QR token + payload
    let qrToken;
    try {
      if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
        qrToken = crypto.randomUUID();
      } else {
        qrToken = `${timesheetId}:${Date.now()}`;
      }
    } catch {
      qrToken = `${timesheetId}:${Date.now()}`;
    }

    const qrPayload = {
      kind: 'DAILY_QR_TIMESHEET',
      token: qrToken,
      timesheet_id: updatedTs.timesheet_id,
      worked_date: workedDateYmd,
      candidate_id: updatedTs.candidate_id || null,
      client_id: finAfter.client_id || updatedTs.client_id || null
    };

    // 9d) Patch timesheet with new QR metadata
    try {
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/timesheets` +
          `?timesheet_id=eq.${enc(timesheetId)}&is_current=eq.true`,
        {
          method: 'PATCH',
          headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
          body: JSON.stringify({
            qr_token: qrToken,
            qr_status: 'PENDING',
            qr_generated_at: now2,
            qr_payload_json: qrPayload,
            updated_at: now2
          })
        }
      );
    } catch (e) {
      console.warn('[TS_DAILY_MANUAL][QR] failed to patch QR metadata for reissue', {
        timesheet_id: timesheetId,
        err: e?.message || String(e)
      });
      return withCORS(
        env,
        req,
        serverError('Failed to update QR metadata for reissued daily timesheet')
      );
    }

    // 9e) Ensure PDF with new QR embedded
    try {
      pdfKey = await ensureTimesheetPdf(env, timesheetId);
      if (pdfKey) {
        await fetch(
          `${env.SUPABASE_URL}/rest/v1/timesheets` +
            `?timesheet_id=eq.${enc(timesheetId)}&is_current=eq.true`,
          {
            method: 'PATCH',
            headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
            body: JSON.stringify({
              manual_pdf_r2_key: pdfKey,
              updated_at: nowIso()
            })
          }
        ).catch(() => {});
      }
    } catch (e) {
      console.warn('[TS_DAILY_MANUAL][QR] ensureTimesheetPdf failed (non-fatal)', {
        timesheet_id: timesheetId,
        err: e?.message || String(e)
      });
    }

    // 9f) Best-effort: email updated QR timesheet to worker (if you use email_outbox)
    try {
      if (pdfKey && updatedTs.candidate_id) {
        const cand = await sbGetOne(
          env,
          `${env.SUPABASE_URL}/rest/v1/candidates` +
            `?id=eq.${enc(updatedTs.candidate_id)}` +
            `&select=id,display_name,email`
        ).catch(() => null);

        const email = cand && cand.email && String(cand.email).trim();
        if (email) {
          const subject =
            workedDateYmd
              ? `Updated daily timesheet for signature – ${workedDateYmd}`
              : 'Updated daily timesheet for signature';

          const bodyText =
            `Your daily timesheet has been updated.\n\n` +
            `The hours on your timesheet were amended by the back office, and any previous QR timesheet for this shift is no longer valid.\n\n` +
            `Please use the attached updated timesheet only.\n`;

          const outboxPayload = [{
            to_email: email,
            subject,
            body_text: bodyText,
            attachments_json: [
              {
                kind: 'R2',
                r2_key: pdfKey,
                filename: `Timesheet_${workedDateYmd || timesheetId}.pdf`,
                content_type: 'application/pdf'
              }
            ],
            created_by_user_id: user.id || null
          }];

          try {
            const ins = await fetch(
              `${env.SUPABASE_URL}/rest/v1/email_outbox`,
              {
                method: 'POST',
                headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
                body: JSON.stringify(outboxPayload)
              }
            );
            if (!ins.ok) {
              const txt = await ins.text().catch(() => '');
              console.warn('[TS_DAILY_MANUAL][QR] email_outbox insert failed', txt);
            }
          } catch (e) {
            console.warn('[TS_DAILY_MANUAL][QR] email enqueue failed (non-fatal)', e?.message || e);
          }
        }
      }
    } catch (e) {
      console.warn('[TS_DAILY_MANUAL][QR] email logic failed (non-fatal)', e?.message || e);
    }

    qrReissued = true;
  }

  // 10) Audit
  try {
    await writeAudit(
      env,
      user,
      'DAILY_MANUAL_UPSERT',
      {
        timesheet_id: timesheetId,
        worked_start_iso: worked_start_iso ?? ts.worked_start_iso,
        worked_end_iso:   worked_end_iso   ?? ts.worked_end_iso,
        break_start_iso:  break_start_iso  ?? ts.break_start_iso,
        break_end_iso:    break_end_iso    ?? ts.break_end_iso,
        break_minutes:    break_minutes    ?? ts.break_minutes,
        revoke_qr:  revokeQr,
        reissue_qr: reissueQr,
        had_qr_before: hadQrBefore,
        qr_revoked:  qrRevoked,
        qr_reissued: qrReissued,
        pdf_key:     pdfKey || null
      },
      { entity: 'timesheets', subject_id: timesheetId, req }
    );
  } catch (e) {
    console.warn('[TS_DAILY_MANUAL][AUDIT] failed', e?.message || e);
  }

  return withCORS(env, req, ok({
    ok: true,
    timesheet_id: timesheetId,
    qr_revoked: qrRevoked,
    qr_reissued: qrReissued,
    pdf_key: pdfKey || null
  }));
}

 async function handleContractWeekManualAuthorise(env, req, weekId) {
  // Second checker: stamp TS authorise + TSFIN → READY_FOR_HR or READY_FOR_INVOICE
  // based on client_settings.requires_hr, and mark the week as AUTHORISED.
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const cw = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(weekId)}&select=id,timesheet_id`
  );
  if (!cw?.timesheet_id) {
    return withCORS(env, req, badRequest('No timesheet linked to this week'));
  }

  const now = nowIso();

  // Load TSFIN first so we can inspect processing_status before stamping anything
  const { rows: finRows } = await sbFetch(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
      `?timesheet_id=eq.${enc(cw.timesheet_id)}` +
      `&is_current=eq.true` +
      `&select=id,client_id,processing_status`
  );
  const fin = finRows?.[0] || null;

  if (fin) {
    const ps = String(fin.processing_status || '').toUpperCase();

    // NEW: guard for QR-print-and-sign flow
    // If TSFIN is in a QR "awaiting signature" state, do NOT auto-promote.
    // The QR auto-process will move it to PENDING_AUTH once the signed PDF is processed.
    if (ps === 'QR_PENDING_SIGNATURE' || ps === 'AWAITING_QR_SIGNATURE') {
      return withCORS(
        env,
        req,
        badRequest('Timesheet is awaiting QR/manual signature; cannot authorise yet')
      );
    }

    // Determine whether this client requires HR validation
    let requiresHr = false;
    if (fin.client_id) {
      const { rows: csRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/client_settings` +
          `?client_id=eq.${enc(fin.client_id)}` +
          `&select=requires_hr` +
          `&order=effective_from.desc&limit=1`
      );
      requiresHr = !!csRows?.[0]?.requires_hr;
    }

    let newStatus = fin.processing_status;
    if (ps === 'PENDING_AUTH' || ps === 'READY_FOR_HR') {
      newStatus = requiresHr ? 'READY_FOR_HR' : 'READY_FOR_INVOICE';
    }

    // Promote TSFIN (unchanged for non-QR flows)
    await fetch(
      `${env.SUPABASE_URL}/rest/v1/timesheets_financials?id=eq.${enc(fin.id)}`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), 'Prefer': 'return-minimal' },
        body: JSON.stringify({
          processing_status: newStatus,
          authorised_by_user_id: user.id,
          authorised_at_utc: now,
          updated_at: now
        })
      }
    ).catch(() => { /* best-effort */ });
  }

  // Stamp timesheet as authorised (we only reach here if not blocked by QR guard)
  await fetch(
    `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(cw.timesheet_id)}&is_current=eq.true`,
    {
      method: 'PATCH',
      headers: { ...sbHeaders(env), 'Prefer': 'return-minimal' },
      body: JSON.stringify({ authorised_at_server: now, updated_at: now })
    }
  ).catch(() => { /* best-effort */ });

  // Update week status → AUTHORISED
  await fetch(
    `${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(weekId)}`,
    {
      method: 'PATCH',
      headers: { ...sbHeaders(env), 'Prefer': 'return-minimal' },
      body: JSON.stringify({ status: 'AUTHORISED', updated_at: now })
    }
  ).catch(() => { /* best-effort */ });

  return withCORS(env, req, ok({ authorised: true, timesheet_id: cw.timesheet_id }));
}

 async function handleContractWeekDeleteTimesheet(env, req, weekId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());
  if (!weekId) return withCORS(env, req, badRequest('contract_week_id is required'));

  const enc = encodeURIComponent;

  const cw = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(weekId)}&select=*`
  );
  if (!cw) {
    return withCORS(env, req, notFound('Week not found'));
  }
  if (!cw.timesheet_id) {
    return withCORS(env, req, badRequest('No timesheet attached'));
  }

  const timesheetId = cw.timesheet_id;

  // Guard 1: current TSFIN must not be paid or invoiced
  const tsfin = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
      `?timesheet_id=eq.${enc(timesheetId)}` +
      `&is_current=eq.true` +
      `&select=paid_at_utc,locked_by_invoice_id`
  );
  if (tsfin?.paid_at_utc) {
    return withCORS(env, req, badRequest('Cannot delete: already paid'));
  }
  if (tsfin?.locked_by_invoice_id) {
    return withCORS(env, req, badRequest('Cannot delete: invoiced'));
  }

  // Check whether any timesheet rows still exist for this id
  const { rows: tsRows } = await sbFetch(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?timesheet_id=eq.${enc(timesheetId)}` +
      `&select=timesheet_id&limit=1`
  );
  const versions = tsRows || [];

  if (!versions.length) {
    // Timesheet id on cw but no rows – just reset the week
    await fetch(
      `${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(weekId)}`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), 'Prefer': 'return-minimal' },
        body: JSON.stringify({
          timesheet_id: null,
          status: 'OPEN',
          updated_at: nowIso()
        })
      }
    ).catch(() => {});
    return withCORS(env, req, ok({ deleted: false, reset: true }));
  }

  // Delete ALL versions for this timesheet_id (manual + electronic)
  const del = await fetch(
    `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(timesheetId)}`,
    {
      method: 'DELETE',
      headers: { ...sbHeaders(env), 'Prefer': 'return-minimal' }
    }
  );
  if (!del.ok) {
    return withCORS(env, req, serverError(await del.text()));
  }

  // Reset week to OPEN so the candidate can (if allowed) resubmit electronically
  await fetch(
    `${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(weekId)}`,
    {
      method: 'PATCH',
      headers: { ...sbHeaders(env), 'Prefer': 'return-minimal' },
      body: JSON.stringify({
        timesheet_id: null,
        status: 'OPEN',
        updated_at: nowIso()
      })
    }
  ).catch(() => {});

  return withCORS(env, req, ok({ deleted: true }));
}



 async function handleContractWeekCreateExpenseSheet(env, req, weekId) {
  // Create an expense-only TS for the week (line_type=EXPENSES)
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const cw = await sbGetOne(env, `${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(weekId)}&select=*`);
  if (!cw) return withCORS(env, req, notFound('Week not found'));
  const contract = await sbGetOne(env, `${env.SUPABASE_URL}/rest/v1/contracts?id=eq.${enc(cw.contract_id)}&select=*`);
  if (!contract) return withCORS(env, req, notFound('Contract not found'));

  const candidate = contract.candidate_id ? await sbGetOne(env, `${env.SUPABASE_URL}/rest/v1/candidates?id=eq.${enc(contract.candidate_id)}&select=id,display_name`) : null;
  const client = contract.client_id ? await sbGetOne(env, `${env.SUPABASE_URL}/rest/v1/clients?id=eq.${enc(contract.client_id)}&select=id,name`) : null;

  const booking_id = makeWeeklyBookingId(candidate?.id, contract, cw);

  const payload = [{
    booking_id, version: 1, is_current: true, status: 'SUBMITTED',
    occupant_key_norm: (candidate?.display_name || String(candidate?.id || 'worker')).toLowerCase(),
    hospital_norm: (contract.display_site || client?.name || String(contract.client_id)).toLowerCase(),
    ward_norm: (contract.ward_hint || 'contract').toLowerCase(),
    job_title_norm: (contract.role || 'weekly').toLowerCase(),
    shift_label_norm: 'weekly-expenses',
    week_ending_date: cw.week_ending_date,
    contract_id: contract.id,
    submission_mode: cw.submission_mode_snapshot,
    manual_pdf_r2_key: null,
    line_type: 'EXPENSES',
    created_at: nowIso(), updated_at: nowIso()
  }];

  const ins = await fetch(`${env.SUPABASE_URL}/rest/v1/timesheets`, {
    method: 'POST', headers: { ...sbHeaders(env), 'Prefer': 'return=representation' }, body: JSON.stringify(payload)
  });
  if (!ins.ok) return withCORS(env, req, serverError(await ins.text()));
  const ts = (await ins.json().catch(()=>[]))[0];

  // Link if week vacant
  if (!cw.timesheet_id) {
    await fetch(`${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(cw.id)}`, {
      method: 'PATCH', headers: { ...sbHeaders(env), 'Prefer': 'return=minimal' },
      body: JSON.stringify({ timesheet_id: ts.timesheet_id, updated_at: nowIso() })
    });
  }

  // Snapshot with zero hours; expenses will be patched via /tsfin/expenses
  const snap = {
    timesheet_id: ts.timesheet_id,
    timesheet_version: ts.version || 1,
    candidate_id: contract.candidate_id,
    client_id: contract.client_id,
    candidate_assignment: 'ASSIGNED',
    processing_status: 'PENDING_AUTH', // will be promoted after manual authorise or when hours TS authorised
    pay_method: contract.pay_method_snapshot,
    total_pay_ex_vat: 0, total_charge_ex_vat: 0, margin_ex_vat: 0,
    hours_day: 0, hours_night: 0, hours_sat: 0, hours_sun: 0, hours_bh: 0,
    created_at: nowIso(),
  };
  await writeSnapshot(env, snap);

  return withCORS(env, req, ok({ timesheet_id: ts.timesheet_id }));
}

