// helpers used above
function hasPayeBank(c) {
  if (!c) return false;
  return !!(c.account_number && c.sort_code); // minimal signal; holder/bank_name optional
}

async function runTsfinWorkerOnce(env, { limit = 50 } = {}) {
  // Local helpers used by both branches
  const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const asNumberLocal = (v) => (v == null ? 0 : Number(v) || 0);
  const enc = encodeURIComponent;

  // Helper: derive Mon–Sun week start from a week-ending date (ymd)
  const computeWeekStartFromWeekEnding = (weYmd) => {
    if (!weYmd) return null;
    const d = new Date(`${weYmd}T00:00:00Z`);
    if (Number.isNaN(d.getTime())) return weYmd;
    d.setUTCDate(d.getUTCDate() - 6);
    const yyyy = d.getUTCFullYear();
    const mm   = String(d.getUTCMonth() + 1).padStart(2, '0');
    const dd   = String(d.getUTCDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
  };

  // ─────────────────────────────────────────────────────────────
  // Weekly helpers (contract-driven)
  // ─────────────────────────────────────────────────────────────

  async function loadWeeklyContext(env, ts) {
    if (!ts || !ts.timesheet_id || !ts.contract_id || !ts.week_ending_date) {
      return null;
    }

    const cw = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/contract_weeks` +
        `?timesheet_id=eq.${enc(ts.timesheet_id)}` +
        `&select=*` +
        `&limit=1`
    );
    if (!cw) return null;

    const contract = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/contracts` +
        `?id=eq.${enc(cw.contract_id)}` +
        `&select=*`
    );
    if (!contract) return null;

    return { cw, contract };
  }

  async function computeWeeklyHours(env, ts, contract) {
    // Canonical shape
    const zeroHours = { day: 0, night: 0, sat: 0, sun: 0, bh: 0 };

    // 1) Preferred path – schedule-driven for weekly timesheets
    if (Array.isArray(ts.actual_schedule_json) && ts.actual_schedule_json.length) {
      const minsByBucket = await resolveBucketsFromSchedule(
        env,
        contract,
        ts.actual_schedule_json
      );
      const hours = {
        day: +(asNumberLocal(minsByBucket.day) / 60).toFixed(2),
        night: +(asNumberLocal(minsByBucket.night) / 60).toFixed(2),
        sat: +(asNumberLocal(minsByBucket.sat) / 60).toFixed(2),
        sun: +(asNumberLocal(minsByBucket.sun) / 60).toFixed(2),
        bh: +(asNumberLocal(minsByBucket.bh) / 60).toFixed(2),
      };
      return hours;
    }

    // 2) For WEEKLY sheets, the schedule is the canonical source.
    // If there is no actual_schedule_json yet, treat hours as 0 and let
    // Issues / holds flag the problem rather than silently falling back.
    const scope = String(ts.sheet_scope || "").toUpperCase();
    if (scope === "WEEKLY") {
      return zeroHours;
    }

    // 3) Legacy fallback for any non-weekly usage (kept for safety)
    const n = (v) => (v == null ? 0 : Number(v) || 0);
    const hours = {
      day: n(ts.hours_day),
      night: n(ts.hours_night),
      sat: n(ts.hours_sat),
      sun: n(ts.hours_sun),
      bh: n(ts.hours_bh),
    };
    return hours;
  }

  async function computeWeeklyAdditionalFromTs(env, ts, cw, contract) {
    let additional_units_json = {};
    let additional_pay_ex_vat = 0;
    let additional_charge_ex_vat = 0;

    const cfgArrRaw = contract.additional_rates_json;
    if (!Array.isArray(cfgArrRaw) || !cfgArrRaw.length) {
      return {
        additional_units_json,
        additional_pay_ex_vat,
        additional_charge_ex_vat,
        additional_margin_ex_vat: 0,
      };
    }

    let cfgArr = cfgArrRaw;
    if (typeof cfgArrRaw === "string") {
      try {
        cfgArr = JSON.parse(cfgArrRaw);
      } catch {
        cfgArr = [];
      }
    }
    if (!Array.isArray(cfgArr)) cfgArr = [];

    let unitsWeek = ts.additional_units_week || {};
    let unitsPerDay = ts.additional_units_per_day || {};
    if (typeof unitsWeek === "string") {
      try {
        unitsWeek = JSON.parse(unitsWeek);
      } catch {
        unitsWeek = {};
      }
    }
    if (typeof unitsPerDay === "string") {
      try {
        unitsPerDay = JSON.parse(unitsPerDay);
      } catch {
        unitsPerDay = {};
      }
    }
    if (!unitsWeek || typeof unitsWeek !== "object") unitsWeek = {};
    if (!unitsPerDay || typeof unitsPerDay !== "object") unitsPerDay = {};

    const weekEnd = cw.week_ending_date; // 'YYYY-MM-DD'
    const dates = [];
    try {
      const weDate = new Date(`${weekEnd}T00:00:00Z`);
      for (let i = 6; i >= 0; i--) {
        const d = new Date(weDate);
        d.setUTCDate(weDate.getUTCDate() - i);
        dates.push(toYmd(d)); // existing helper, returns YYYY-MM-DD
      }
    } catch {
      // ignore – we can still use ONE_PER_WEEK units
    }

    let bhSet = new Set();
    try {
      const policy = await loadClientTimePolicy(env, contract.client_id);
      if (policy && policy.bhList) {
        if (policy.bhList instanceof Set) {
          bhSet = policy.bhList;
        } else if (Array.isArray(policy.bhList)) {
          bhSet = new Set(policy.bhList);
        }
      }
    } catch {
      // fall back to empty set
    }

    const dow = (ymd) => {
      try {
        const d = new Date(`${ymd}T00:00:00Z`);
        return d.getUTCDay(); // 0=Sun..6=Sat
      } catch {
        return null;
      }
    };

    const freqEnum = new Set([
      "ONE_PER_WEEK",
      "ONE_PER_DAY",
      "WEEKENDS_AND_BH_ONLY",
      "WEEKDAYS_EXCL_BH_ONLY",
    ]);

    for (const cfg of cfgArr) {
      if (!cfg || !cfg.code) continue;
      const code = String(cfg.code).toUpperCase();

      const freqRaw = (cfg.frequency || "").toString().toUpperCase();
      const freq = freqEnum.has(freqRaw) ? freqRaw : "ONE_PER_WEEK";

      const weekUnits = Number((unitsWeek && unitsWeek[code]) || 0) || 0;
      const perDayRaw =
        unitsPerDay && typeof unitsPerDay[code] === "object"
          ? unitsPerDay[code]
          : {};

      let unitCount = 0;
      const perDayOut = {};

      if (freq === "ONE_PER_WEEK") {
        unitCount = weekUnits;
      } else {
        for (const ymd of dates) {
          const u = Number(perDayRaw?.[ymd] || 0) || 0;
          if (!u) continue;

          const d = dow(ymd);
          const isBh = bhSet.has(ymd);

          let include = false;
          if (freq === "ONE_PER_DAY") {
            include = true;
          } else if (freq === "WEEKENDS_AND_BH_ONLY") {
            include = isBh || d === 0 || d === 6;
          } else if (freq === "WEEKDAYS_EXCL_BH_ONLY") {
            include = !isBh && d != null && d >= 1 && d <= 5;
          }

          if (!include) continue;
          unitCount += u;
          perDayOut[ymd] = (perDayOut[ymd] || 0) + u;
        }
      }

      if (!unitCount || !Number.isFinite(unitCount) || unitCount <= 0) continue;

      const payRate = Number(cfg.pay_rate ?? 0) || 0;
      const chargeRate = Number(cfg.charge_rate ?? 0) || 0;

      const payEx = round2(unitCount * payRate);
      const chgEx = round2(unitCount * chargeRate);

      additional_units_json[code] = {
        bucket_name: cfg.bucket_name || null,
        unit_name: cfg.unit_name || null,
        frequency: freq,
        unit_count: unitCount,
        pay_rate: payRate,
        charge_rate: chargeRate,
        pay_ex_vat: payEx,
        charge_ex_vat: chgEx,
        days: Object.keys(perDayOut).length ? perDayOut : undefined,
      };

      additional_pay_ex_vat += payEx;
      additional_charge_ex_vat += chgEx;
    }

    additional_pay_ex_vat = round2(additional_pay_ex_vat);
    additional_charge_ex_vat = round2(additional_charge_ex_vat);
    const additional_margin_ex_vat = round2(
      additional_charge_ex_vat - additional_pay_ex_vat
    );

    return {
      additional_units_json,
      additional_pay_ex_vat,
      additional_charge_ex_vat,
      additional_margin_ex_vat,
    };
  }


  // Build a timesheets_financials snapshot for a weekly, contract-driven TS.
  // basis = 'CONTRACT_WEEKLY' (requires enum extension).
  

   async function pruneOldHrWeeklyImports(env) {
  const enc = encodeURIComponent;

  const now = new Date();
  const ninetyDaysMs = 90 * 24 * 60 * 60 * 1000;
  const threshold = new Date(now.getTime() - ninetyDaysMs);
  const thresholdIso = threshold.toISOString();

  try {
    // 1) Find HR weekly imports that were applied > 90 days ago and not yet pruned
    const { rows: impRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/hr_imports` +
        `?import_scope=eq.HR_WEEKLY` +
        `&applied_at=is.not.null` +
        `&pruned_at=is.null` +
        `&applied_at=lt.${enc(thresholdIso)}` +
        `&select=id`
    );

    const importIds = (impRows || [])
      .map(r => r.id)
      .filter(Boolean);

    if (!importIds.length) {
      // Nothing to prune
      return { ok: true, pruned_imports: 0, pruned_rows: 0 };
    }

    const idsParam = importIds.map(enc).join(',');

    // 2) Delete staged hr_rows for these imports
    let prunedRows = 0;
    try {
      const delRes = await fetch(
        `${env.SUPABASE_URL}/rest/v1/hr_rows?import_id=in.(${idsParam})`,
        {
          method: 'DELETE',
          headers: {
            ...sbHeaders(env),
            Prefer: 'count=exact'
          }
        }
      );
      if (!delRes.ok) {
        const txt = await delRes.text().catch(() => '');
        console.warn('[pruneOldHrWeeklyImports] hr_rows delete failed', {
          status: delRes.status,
          body: txt
        });
      } else {
        const range = delRes.headers.get('content-range');
        // content-range is usually "0-9/10" → total after slash
        if (range && range.includes('/')) {
          const parts = range.split('/');
          const totalStr = parts[1] || '';
          const totalNum = Number(totalStr);
          if (Number.isFinite(totalNum)) {
            prunedRows = totalNum;
          }
        }
      }
    } catch (e) {
      console.warn('[pruneOldHrWeeklyImports] hr_rows delete threw', {
        err: e?.message || String(e)
      });
    }

    // 3) Mark hr_imports as pruned
    try {
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/hr_imports?id=in.(${idsParam})`,
        {
          method: 'PATCH',
          headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
          body: JSON.stringify({ pruned_at: new Date().toISOString() })
        }
      );
    } catch (e) {
      console.warn('[pruneOldHrWeeklyImports] hr_imports patch failed', {
        import_ids: importIds,
        err: e?.message || String(e)
      });
    }

    return {
      ok: true,
      pruned_imports: importIds.length,
      pruned_rows: prunedRows,
      import_ids: importIds
    };
  } catch (e) {
    console.error('[pruneOldHrWeeklyImports] unexpected error', {
      err: e?.message || String(e)
    });
    return { ok: false, error: e?.message || String(e) };
  }
}

  // ─────────────────────────────────────────────────────────────
  // HR cross-check enrichment helper (NEW)
  // ─────────────────────────────────────────────────────────────

  async function enrichTsfinWithHrCrosscheck(env, ts, tsfinRow) {
    try {
      if (!ts || !tsfinRow) return;

 const scope = String(ts.sheet_scope || "").toUpperCase();
if (scope !== 'WEEKLY') {
  // Non-weekly timesheets should not carry HR cross-check flags
  await fetch(
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials?id=eq.${enc(tsfinRow.id)}`,
    {
      method: 'PATCH',
      headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
      body: JSON.stringify({
        hr_crosscheck_status: null,
        hr_crosscheck_issues: null
      })
    }
  ).catch(() => {});
  return;
}


      // Derive key fields
      const clientId    = tsfinRow.client_id || ts.client_id || null;
      const candidateId = tsfinRow.candidate_id || ts.candidate_id || null;
      const weekEnding  = ts.week_ending_date || tsfinRow.week_ending_date || null;

      if (!clientId || !candidateId || !weekEnding) {
        // Clear HR flags if we don't have enough to cross-check
        await fetch(
          `${env.SUPABASE_URL}/rest/v1/timesheets_financials?id=eq.${enc(tsfinRow.id)}`,
          {
            method: 'PATCH',
            headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
            body: JSON.stringify({
              hr_crosscheck_status: null,
              hr_crosscheck_issues: null
            })
          }
        ).catch(() => {});
        return;
      }

      // Load client settings to see if HR cross-check applies
      let requiresHr = false;
      let noTsRequired = false;
      try {
        const { rows: csRows } = await sbFetch(
          env,
          `${env.SUPABASE_URL}/rest/v1/client_settings` +
          `?client_id=eq.${enc(clientId)}` +
          `&select=client_id,requires_hr,no_timesheet_required` +
          `&order=effective_from.desc` +
          `&limit=1`
        );
        const cs = csRows?.[0] || null;
        if (cs) {
          requiresHr   = !!cs.requires_hr;
          noTsRequired = !!cs.no_timesheet_required;
        }
      } catch {
        // If we can't load client_settings, treat as no HR cross-check
      }

      if (!requiresHr || noTsRequired) {
        // HR cross-check not required for this client; clear HR fields
        await fetch(
          `${env.SUPABASE_URL}/rest/v1/timesheets_financials?id=eq.${enc(tsfinRow.id)}`,
          {
            method: 'PATCH',
            headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
            body: JSON.stringify({
              hr_crosscheck_status: null,
              hr_crosscheck_issues: null
            })
          }
        ).catch(() => {});
        return;
      }

      const weekStart = computeWeekStartFromWeekEnding(weekEnding) || weekEnding;

      // Load HR (HealthRoster) shifts for this client+candidate+week
      let hrShifts = [];
      try {
        const { rows } = await sbFetch(
          env,
          `${env.SUPABASE_URL}/rest/v1/nhsp_shifts` +
          `?source_system=eq.HEALTHROSTER` +
          `&client_id=eq.${enc(clientId)}` +
          `&candidate_id=eq.${enc(candidateId)}` +
          `&work_date=gte.${enc(weekStart)}` +
          `&work_date=lte.${enc(weekEnding)}` +
          `&select=id,work_date,start_utc,end_utc,break_mins,ref_num,payload_json`
        );
        hrShifts = rows || [];
      } catch {
        hrShifts = [];
      }

      // Build per-day paid minutes from HR
      const hrMinsByDate = {};
      const hrHasAny = hrShifts.length > 0;

      function accumulateMins(map, ymd, startIso, endIso, breakMins) {
        if (!ymd || !startIso || !endIso) return;
        try {
          const start = new Date(startIso);
          const end   = new Date(endIso);
          if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) return;
          let mins = (end.getTime() - start.getTime()) / 60000;
          mins -= Number(breakMins || 0);
          if (mins < 0) mins = 0;
          map[ymd] = (map[ymd] || 0) + mins;
        } catch {
          // ignore bad rows
        }
      }

      for (const sh of hrShifts) {
        accumulateMins(hrMinsByDate, sh.work_date, sh.start_utc, sh.end_utc, sh.break_mins);
      }

      // Build per-day paid minutes from TS schedule
      const tsMinsByDate = {};
      let tsHasAny = false;
      if (Array.isArray(ts.actual_schedule_json)) {
        for (const seg of ts.actual_schedule_json) {
          if (!seg) continue;
          const ymd = seg.date || seg.date_ymd || seg.work_date || null;
          const startIso = seg.start_utc || seg.start || null;
          const endIso   = seg.end_utc   || seg.end   || null;
          const bmins    = seg.break_mins || seg.break_minutes || 0;
          accumulateMins(tsMinsByDate, ymd, startIso, endIso, bmins);
        }
      }

      tsHasAny = Object.values(tsMinsByDate).some(v => (v || 0) > 0);

      // Build external_source_rows_json.HR_WEEKLY snapshot
      const external = tsfinRow.external_source_rows_json && typeof tsfinRow.external_source_rows_json === 'object'
        ? { ...tsfinRow.external_source_rows_json }
        : {};

      external.HR_WEEKLY = hrShifts.map(sh => ({
        date: sh.work_date,
        source_system: 'HEALTHROSTER',
        reference: sh.ref_num || (sh.payload_json && (sh.payload_json.reference || sh.payload_json.ref_num)) || null,
        nhsp_shift_id: sh.id,
        raw_row: sh.payload_json || null
      }));

      let issues = [];
      let status = null;

      const epsilonHours = 0.01; // ~0.6 minutes

      const allDates = new Set([
        ...Object.keys(hrMinsByDate),
        ...Object.keys(tsMinsByDate)
      ]);

      if (!hrHasAny && tsHasAny) {
        // Timesheet has hours but there are no HR rows at all
        status = 'HR_HOURS_MISSING';
        issues.push('HR_HOURS_MISSING');
      } else if (!hrHasAny && !tsHasAny) {
        // Neither side has hours → treat as "no cross-check" (no issues)
        status = null;
        issues = [];
      } else {
        let anyMissing = false;
        let anyMismatch = false;

        for (const ymd of allDates) {
          const hrM = hrMinsByDate[ymd] || 0;
          const tsM = tsMinsByDate[ymd] || 0;
          const hrH = hrM / 60;
          const tsH = tsM / 60;

          if (tsM > 0 && hrM === 0) {
            anyMissing = true;
          } else if (hrM > 0 && tsM === 0) {
            // HR has shift, TS has none → hours mismatch as well
            anyMismatch = true;
          } else if (Math.abs(hrH - tsH) > epsilonHours) {
            anyMismatch = true;
          }
        }

        if (anyMismatch) {
          status = 'HOURS_MISMATCH_HR';
          issues.push('HOURS_MISMATCH_HR');
        }
        if (anyMissing) {
          // Distinct issue from mismatch
          if (!issues.includes('HR_HOURS_MISSING')) {
            issues.push('HR_HOURS_MISSING');
          }
          if (!status) status = 'HR_HOURS_MISSING';
        }
        if (!anyMismatch && !anyMissing) {
          status = 'OK';
          issues = [];
        }
      }

      // Duplicate contracts check for this client/candidate/week
      try {
        const { rows: dupRows } = await sbFetch(
          env,
          `${env.SUPABASE_URL}/rest/v1/contract_weeks` +
          `?week_ending_date=eq.${enc(weekEnding)}` +
          `&select=id,contract_id,status`
        );
        const cwRows = dupRows || [];
        if (cwRows.length > 1) {
          // Need to check contracts belong to this client & candidate
          const cwIds = cwRows.map(r => r.contract_id).filter(Boolean);
          if (cwIds.length) {
            const { rows: conRows } = await sbFetch(
              env,
              `${env.SUPABASE_URL}/rest/v1/contracts` +
              `?id=in.(${cwIds.map(enc).join(',')})` +
              `&select=id,client_id,candidate_id,status`
            );
            const relevant = (conRows || []).filter(
              c => c.client_id === clientId && c.candidate_id === candidateId && c.status !== 'CANCELLED'
            );
            if (relevant.length > 1) {
              if (!issues.includes('DUPLICATE_CONTRACTS')) {
                issues.push('DUPLICATE_CONTRACTS');
              }
              // We don't override status here; view-level needs_attention will pick it up.
            }
          }
        }
      } catch {
        // duplicate check failure is non-fatal
      }

     // Decide if this TSFIN row should be flagged as needing attention
const needsAttention =
  (status && status !== 'OK') ||
  (Array.isArray(issues) && issues.includes('DUPLICATE_CONTRACTS'));

// Write back HR cross-check fields + needs_attention
const patch = {
  hr_crosscheck_status: status,
  hr_crosscheck_issues: issues.length ? issues : null,
  external_source_rows_json: external,
  needs_attention: needsAttention,
  updated_at: new Date().toISOString()
};

await fetch(
  `${env.SUPABASE_URL}/rest/v1/timesheets_financials?id=eq.${enc(tsfinRow.id)}`,
  {
    method: 'PATCH',
    headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
    body: JSON.stringify(patch)
  }
).catch(() => {});

    } catch (e) {
      console.warn('[TSFIN] enrichTsfinWithHrCrosscheck failed', {
        timesheet_id: ts?.timesheet_id,
        tsfin_id: tsfinRow?.id,
        err: e?.message || String(e)
      });
    }
  }

  // ─────────────────────────────────────────────────────────────
  // Daily / Rota helper (SELF_REPORTED basis)
  // ─────────────────────────────────────────────────────────────
  // (unchanged here; Daily snapshot builder is elsewhere in the file)

  // ─────────────────────────────────────────────────────────────
  // Worker core
  // ─────────────────────────────────────────────────────────────

  const lease = await sbRpc(env, "tsfin_dequeue_batch", { p_limit: limit });
  if (!Array.isArray(lease) || !lease.length)
    return { picked: 0, ok: 0, fail: 0 };

  let ok = 0, fail = 0;

  for (const item of lease) {
    try {
      const ts = await loadCurrentTimesheet(env, item.timesheet_id);
      if (!ts) {
        await sbRpc(env, "tsfin_mark_revoked", {
          p_timesheet_id: item.timesheet_id,
        });
        await sbRpc(env, "tsfin_work_success", { p_id: item.id });
        ok++;
        continue;
      }

      // NEW: if this timesheet already has a current NHSP / NHSP_ADJUSTMENT snapshot,
      // do NOT overwrite it with a generic CONTRACT_WEEKLY or SELF_REPORTED snapshot.
      try {
        const { rows: curFinRows } = await sbFetch(
          env,
          `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
          `?timesheet_id=eq.${enc(ts.timesheet_id)}` +
          `&is_current=eq.true` +
          `&select=basis` +
          `&limit=1`
        );
        const curBasis = (curFinRows && curFinRows[0] && curFinRows[0].basis) || null;
        if (curBasis === 'NHSP' || curBasis === 'NHSP_ADJUSTMENT') {
          await sbRpc(env, "tsfin_work_success", { p_id: item.id });
          ok++;
          continue;
        }
      } catch {
        // if this lookup fails, fall back to normal behaviour
      }

      if (!ts.authorised_at_server) {
        // Only build TSFIN for authorised timesheets
        await sbRpc(env, "tsfin_work_success", { p_id: item.id });
        ok++;
        continue;
      }

      const weeklyCtx = await loadWeeklyContext(env, ts);
      if (weeklyCtx) {
        // Weekly CONTRACT_WEEKLY snapshot
        await buildWeeklySnapshot(env, ts, weeklyCtx.cw, weeklyCtx.contract);

        // After writing the snapshot, load the current TSFIN row and enrich with HR cross-check if applicable
        try {
          const { rows: tfRows } = await sbFetch(
            env,
            `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
            `?timesheet_id=eq.${enc(ts.timesheet_id)}` +
            `&is_current=eq.true` +
            `&select=*` +
            `&limit=1`
          );
          const tsfinRow = tfRows?.[0] || null;
          if (tsfinRow) {
            await enrichTsfinWithHrCrosscheck(env, ts, tsfinRow);
          }
        } catch (e) {
          console.warn('[TSFIN] failed to load TSFIN for HR cross-check', {
            timesheet_id: ts.timesheet_id,
            err: e?.message || String(e)
          });
        }

        await sbRpc(env, "tsfin_work_success", { p_id: item.id });
        ok++;
        continue;
      }

      // ── DAILY / ROTA branch ──────────────────────────────
      await buildDailySnapshot(env, ts);
      // (HR cross-check does not apply to daily rota; nothing extra here)

      await sbRpc(env, "tsfin_work_success", { p_id: item.id });
      ok++;
    } catch (e) {
      await sbRpc(env, "tsfin_work_fail", {
        p_id: item.id,
        p_error: String(e?.message || e),
      });
      fail++;
    }
  }

  return { picked: lease.length, ok, fail };
}


// Run HR weekly cross-check in bulk for every (client, candidate, week)
// touched by a given HR_WEEKLY import.
//
// This helper is invoked from handleHrAutoprocessApply(env, req, importId).
async function applyWeeklyHealthRosterCrosscheck(env, { import_id }) {
  const enc = encodeURIComponent;
  if (!import_id) return { triples: 0, timesheets_checked: 0 };

  // ─────────────────────────────────────────────
  // Step 1: fetch hr_rows for this import
  // ─────────────────────────────────────────────

  let hrRows = [];
  try {
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/hr_rows` +
      `?import_id=eq.${enc(import_id)}` +
      `&select=client_id,candidate_id,week_ending_date,work_date,import_type`
    );
    hrRows = rows || [];
  } catch (e) {
    console.warn('[applyWeeklyHealthRosterCrosscheck] failed to load hr_rows', {
      import_id,
      err: e?.message || String(e)
    });
    return { triples: 0, timesheets_checked: 0 };
  }

  if (!hrRows.length) {
    return { triples: 0, timesheets_checked: 0 };
  }

  // Filter down to HEALTHROSTER_WEEKLY rows if import_type is present,
  // otherwise just use all rows for this import.
  const filteredRows = hrRows.filter(r => {
    const t = (r.import_type || '').toString().toUpperCase();
    return !r.import_type || t === 'HEALTHROSTER_WEEKLY';
  });

  if (!filteredRows.length) {
    return { triples: 0, timesheets_checked: 0 };
  }

  // ─────────────────────────────────────────────
  // Step 2: compute distinct (client_id, candidate_id, week_ending_date)
  // ─────────────────────────────────────────────

  const triplesMap = new Map(); // key -> { client_id, candidate_id, week_ending_date }

  // cache client week-ending weekday to avoid repeated lookups
  const clientWeekdayCache = new Map(); // client_id -> week_ending_weekday (0=Sun..6=Sat, default 0)

  async function getWeekEndingForRow(row) {
    const clientId = row.client_id || null;
    let weekEnd    = row.week_ending_date || null;
    const workDate = row.work_date || null;

    if (weekEnd) return weekEnd;
    if (!clientId || !workDate) return null;

    // Look up client's configured week-ending weekday
    let weDow = clientWeekdayCache.get(clientId);
    if (weDow === undefined) {
      weDow = 0;
      try {
        const { rows: csRows } = await sbFetch(
          env,
          `${env.SUPABASE_URL}/rest/v1/client_settings` +
          `?client_id=eq.${enc(clientId)}` +
          `&select=client_id,week_ending_weekday` +
          `&order=effective_from.desc` +
          `&limit=1`
        );
        const cs = csRows?.[0] || null;
        if (cs && cs.week_ending_weekday != null) {
          const v = Number(cs.week_ending_weekday);
          if (Number.isInteger(v)) weDow = v;
        }
      } catch {
        weDow = 0;
      }
      clientWeekdayCache.set(clientId, weDow);
    }

    try {
      const d = new Date(`${workDate}T00:00:00Z`);
      if (Number.isNaN(d.getTime())) return null;
      // Move forward to the client's configured week-ending weekday
      while (d.getUTCDay() !== weDow) {
        d.setUTCDate(d.getUTCDate() + 1);
      }
      const yyyy = d.getUTCFullYear();
      const mm   = String(d.getUTCMonth() + 1).padStart(2, '0');
      const dd   = String(d.getUTCDate()).padStart(2, '0');
      return `${yyyy}-${mm}-${dd}`;
    } catch {
      return null;
    }
  }

  for (const r of filteredRows) {
    const clientId    = r.client_id || null;
    const candidateId = r.candidate_id || null;
    if (!clientId || !candidateId) continue;

    // Resolve week_ending_date from hr_rows.week_ending_date or work_date + client settings
    // using the same convention as weekly TS logic.
    // eslint-disable-next-line no-await-in-loop
    const weekEnd = await getWeekEndingForRow(r);
    if (!weekEnd) continue;

    const key = `${clientId}__${candidateId}__${weekEnd}`;
    if (!triplesMap.has(key)) {
      triplesMap.set(key, {
        client_id: clientId,
        candidate_id: candidateId,
        week_ending_date: weekEnd
      });
    }
  }

  if (!triplesMap.size) {
    return { triples: 0, timesheets_checked: 0 };
  }

  // ─────────────────────────────────────────────
  // Step 3: for each triple, run enrichTsfinWithHrCrosscheck on all TSs
  // ─────────────────────────────────────────────

  let timesheetsChecked = 0;

  for (const triple of triplesMap.values()) {
    const { client_id, candidate_id, week_ending_date } = triple;

    // Load weekly timesheets for this client+candidate+week
    let tsRows = [];
    try {
      const res = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?client_id=eq.${enc(client_id)}` +
        `&candidate_id=eq.${enc(candidate_id)}` +
        `&sheet_scope=eq.WEEKLY` +
        `&week_ending_date=eq.${enc(week_ending_date)}` +
        `&is_current=eq.true` +
        `&select=*`
      );
      tsRows = res.rows || [];
    } catch (e) {
      console.warn('[applyWeeklyHealthRosterCrosscheck] failed to load timesheets', {
        import_id,
        client_id,
        candidate_id,
        week_ending_date,
        err: e?.message || String(e)
      });
      continue;
    }

    if (!tsRows.length) {
      // If there is a contract_week but no TS, TSFIN will be created later;
      // enrichTsfinWithHrCrosscheck will run then via the TSFIN worker.
      continue;
    }

    for (const ts of tsRows) {
      // Load current TSFIN snapshot for this TS
      let tfRows;
      try {
        const resTf = await sbFetch(
          env,
          `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
          `?timesheet_id=eq.${enc(ts.timesheet_id)}` +
          `&is_current=eq.true` +
          `&select=*` +
          `&limit=1`
        );
        tfRows = resTf.rows || [];
      } catch (e) {
        console.warn('[applyWeeklyHealthRosterCrosscheck] failed to load TSFIN', {
          import_id,
          timesheet_id: ts.timesheet_id,
          err: e?.message || String(e)
        });
        continue;
      }

      const tsfinRow = tfRows[0];
      if (!tsfinRow) {
        // No TSFIN yet; worker will handle it later.
        continue;
      }

      try {
        // Reuse the same cross-check helper used by the worker
        await enrichTsfinWithHrCrosscheck(env, ts, tsfinRow);
        timesheetsChecked++;
      } catch (e) {
        console.warn('[applyWeeklyHealthRosterCrosscheck] enrich failed', {
          import_id,
          timesheet_id: ts.timesheet_id,
          tsfin_id: tsfinRow.id,
          err: e?.message || String(e)
        });
      }
    }
  }

  return { triples: triplesMap.size, timesheets_checked: timesheetsChecked };
}




async function buildDailySnapshot(env, ts) {
  const occupantKey = ts.occupant_key_norm || null;
  const candidate   = await loadCandidate(env, occupantKey);
  const candidate_id = candidate?.id || null;
  const candidate_assignment = candidate ? "ASSIGNED" : "UNASSIGNED";

  // Client via alias-aware resolver
  const client_id = await resolveClientId(env, ts.hospital_norm || null);

  // Worked date in local timezone for policy & rates
  const workedDateYmd = ts.worked_start_iso
    ? toLocalParts(ts.worked_start_iso, null).ymd
    : null;

  // Client policy (HR requirements, BH, day/night windows, etc.)
  const policy = await loadPolicy(env, client_id, workedDateYmd);

  // Build base segments from worked_start / worked_end and subtract breaks
  let segments = [];
  if (ts.worked_start_iso && ts.worked_end_iso) {
    segments.push([ts.worked_start_iso, ts.worked_end_iso]);
  }
  segments = subtractBreak(
    segments,
    ts.break_start_iso || null,
    ts.break_end_iso   || null,
    ts.break_minutes   || null
  );

  // Classify into day/night/sat/sun/bh hours
  const hours = classifyMinutes(env, policy, segments);

  // Resolve rates using candidate, client, role, band, date
  const rates = await resolveRates(env, {
    candidate_id: candidate_id,
    client_id,
    role: ts.job_title_norm || null,
    band: ts.band || null,
    dateYmd: workedDateYmd,
  });

  // Detect missing rates for any used bucket
  const missingRates = anyMissingRates(
    {
      day:   hours.hours_day,
      night: hours.hours_night,
      sat:   hours.hours_sat,
      sun:   hours.hours_sun,
      bh:    hours.hours_bh,
    },
    rates.pay,
    rates.charge
  );

  // Determine pay_method for this snapshot
  const pay_method =
    candidate?.pay_method === "UMBRELLA"
      ? "UMBRELLA"
      : candidate?.pay_method === "PAYE"
      ? "PAYE"
      : ts.pay_method || null;

  // Pay-channel state via resolveEffectivePayChannel (only meaningful once IDs known)
  let payChannelBad = false;
  try {
    if (candidate_id && client_id && typeof resolveEffectivePayChannel === 'function') {
      let umbrella = null;
      if (candidate?.umbrella_id) {
        umbrella = await sbGetOne(
          env,
          `${env.SUPABASE_URL}/rest/v1/umbrellas` +
            `?id=eq.${enc(candidate.umbrella_id)}` +
            `&select=id,name,bank_name,sort_code,account_number` +
            `&limit=1`
        );
      }

      const channel = resolveEffectivePayChannel({
        pay_method: pay_method || candidate?.pay_method || null,
        candidate,
        umbrella,
      });

      payChannelBad = !channel || channel.ok === false;
    }
  } catch (e) {
    console.warn('[TSFIN][buildDailySnapshot] resolveEffectivePayChannel failed', e);
    payChannelBad = true;
  }

  const requiresHr = !!policy?.requires_hr;

  // ── ID-first ladder + issue flags ──
  let processing_status;
  let hasRateIssue       = false;
  let hasPayChannelIssue = false;

  if (!candidate_id) {
    processing_status = "UNASSIGNED";
  } else if (!client_id) {
    processing_status = "CLIENT_UNRESOLVED";
  } else if (missingRates) {
    processing_status   = "RATE_MISSING";
    hasRateIssue        = true;
    hasPayChannelIssue  = !!payChannelBad;
  } else if (payChannelBad) {
    processing_status   = "PAY_CHANNEL_MISSING";
    hasRateIssue        = false;
    hasPayChannelIssue  = true;
  } else if (requiresHr) {
    processing_status   = "READY_FOR_HR";
    hasRateIssue        = false;
    hasPayChannelIssue  = false;
  } else {
    processing_status   = "READY_FOR_INVOICE";
    hasRateIssue        = false;
    hasPayChannelIssue  = false;
  }

  const pay = rates.pay || {
    day: 0,
    night: 0,
    sat: 0,
    sun: 0,
    bh: 0,
  };
  const charge = rates.charge || {
    day: 0,
    night: 0,
    sat: 0,
    sun: 0,
    bh: 0,
  };

  const total_pay_ex_vat = round2(
    hours.hours_day   * asNumberLocal(pay.day)   +
    hours.hours_night * asNumberLocal(pay.night) +
    hours.hours_sat   * asNumberLocal(pay.sat)   +
    hours.hours_sun   * asNumberLocal(pay.sun)   +
    hours.hours_bh    * asNumberLocal(pay.bh)
  );

  const total_charge_ex_vat = round2(
    hours.hours_day   * asNumberLocal(charge.day)   +
    hours.hours_night * asNumberLocal(charge.night) +
    hours.hours_sat   * asNumberLocal(charge.sat)   +
    hours.hours_sun   * asNumberLocal(charge.sun)   +
    hours.hours_bh    * asNumberLocal(charge.bh)
  );

  const margin_ex_vat = round2(total_charge_ex_vat - total_pay_ex_vat);

  // "Lite" payment-ready check purely for holiday pay snapshot
  const paymentReadyLite = !!(
    pay_method === "PAYE" &&
    !missingRates &&
    !payChannelBad
  );

  const pay_wtr_rate_pct_snapshot =
    paymentReadyLite
      ? (asNumberLocal(policy?.holiday_pay_pct) ?? null)
      : null;

  const invoice_breakdown_json = {
    mode: "AGGREGATE",
    base_hours: {
      day:   hours.hours_day,
      night: hours.hours_night,
      sat:   hours.hours_sat,
      sun:   hours.hours_sun,
      bh:    hours.hours_bh,
      pay_rates: {
        day:   rates.pay?.day   ?? null,
        night: rates.pay?.night ?? null,
        sat:   rates.pay?.sat   ?? null,
        sun:   rates.pay?.sun   ?? null,
        bh:    rates.pay?.bh    ?? null,
      },
      charge_rates: {
        day:   rates.charge?.day   ?? null,
        night: rates.charge?.night ?? null,
        sat:   rates.charge?.sat   ?? null,
        sun:   rates.charge?.sun   ?? null,
        bh:    rates.charge?.bh    ?? null,
      },
      pay_ex_vat:    total_pay_ex_vat,
      charge_ex_vat: total_charge_ex_vat,
    },
    additional: {
      units: {},
      pay_ex_vat: 0,
      charge_ex_vat: 0,
      margin_ex_vat: 0,
    },
    totals: {
      total_pay_ex_vat,
      total_charge_ex_vat,
      margin_ex_vat,
    },
  };

  const snapshot = {
    timesheet_id: ts.timesheet_id,
    timesheet_version: ts.version || 1,
    basis: "SELF_REPORTED", // daily/rota self-reported

    occupant_key_norm: ts.occupant_key_norm || null,
    worked_start_iso: ts.worked_start_iso || null,
    worked_end_iso:   ts.worked_end_iso   || null,
    break_start_iso:  ts.break_start_iso  || null,
    break_end_iso:    ts.break_end_iso    || null,
    break_minutes:    ts.break_minutes    || null,

    candidate_id,
    client_id: client_id || null,
    role: ts.job_title_norm || null,
    band: ts.band || null,
    pay_method,

    policy_snapshot_json: policy,
    rate_source_refs_json: rates.source,

    hours_day:   hours.hours_day,
    hours_night: hours.hours_night,
    hours_sat:   hours.hours_sat,
    hours_sun:   hours.hours_sun,
    hours_bh:    hours.hours_bh,

    pay_day:      rates.pay?.day   ?? null,
    pay_night:    rates.pay?.night ?? null,
    pay_sat:      rates.pay?.sat   ?? null,
    pay_sun:      rates.pay?.sun   ?? null,
    pay_bh:       rates.pay?.bh    ?? null,
    charge_day:   rates.charge?.day   ?? null,
    charge_night: rates.charge?.night ?? null,
    charge_sat:   rates.charge?.sat   ?? null,
    charge_sun:   rates.charge?.sun   ?? null,
    charge_bh:    rates.charge?.bh    ?? null,

    total_hours: round2(
      hours.hours_day +
      hours.hours_night +
      hours.hours_sat +
      hours.hours_sun +
      hours.hours_bh
    ),
    total_pay_ex_vat,
    total_charge_ex_vat,
    margin_ex_vat,

    additional_units_json: {},
    additional_pay_ex_vat: 0,
    additional_charge_ex_vat: 0,
    additional_margin_ex_vat: 0,

    pay_wtr_rate_pct_snapshot,
    candidate_assignment,
    processing_status,

    // NEW issue flags
    has_rate_issue:        hasRateIssue,
    has_pay_channel_issue: hasPayChannelIssue,

    invoice_breakdown_json,
  };

  await writeSnapshot(env, snapshot);
}


// ---------------------------
// API: Manual drain
// ---------------------------
async function handleTsfinDrain(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();
  const body = await parseJSONBody(req).catch(() => null);
  const limit = Math.min(Math.max(parseInt(body?.limit || '50', 10) || 50, 1), 500);
  const res = await runTsfinWorkerOnce(env, { limit });
  return ok(res);
}

// ---------------------------
// API: Recompute (enqueue)
// ---------------------------
async function handleTsfinRecompute(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();
  const body = await parseJSONBody(req).catch(() => null);
  const ids = Array.isArray(body?.timesheet_ids) ? body.timesheet_ids.slice(0, 200) : [];
  if (!ids.length) return badRequest('timesheet_ids array required');
  for (const tsid of ids) await sbRpc(env, 'enqueue_ts_financials', { timesheet_id: tsid, reason: 'MANUAL' });
  return ok({ enqueued: ids.length });
}

// ----------------------------------------
// GET TSFIN (include exp/mileage/PO fields)
// ----------------------------------------
async function handleTsfinFinancials(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized();

  const sp = new URL(req.url).searchParams;
  const ids = splitCsv(sp.get('timesheet_ids'));

  let url = `${env.SUPABASE_URL}/rest/v1/timesheets_financials?is_current=eq.true`;
  const select = [
    '*',
    'expenses_pay_ex_vat','expenses_charge_ex_vat','expenses_description','expenses_evidence_r2_key',
    'mileage_pay_ex_vat','mileage_charge_ex_vat','mileage_evidence_r2_key','mileage_pay_rate','mileage_charge_rate',
    'po_number',
    'candidate_id',
    'pay_method'
  ];
  url += `&select=${select.join(',')}`;
  if (ids.length) url += `&timesheet_id=in.(${ids.map(encodeURIComponent).join(',')})`;

  const { rows } = await sbFetch(env, url, false);

  const candIds = Array.from(new Set((rows || []).map((r) => r.candidate_id).filter(Boolean)));
  let candidatesById = new Map();
  let umbrellasById = new Map();

  if (candIds.length) {
    const candParam = candIds.map(encodeURIComponent).join(',');
    const { rows: candRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/candidates` +
      `?select=id,umbrella_id,account_holder,bank_name,sort_code,account_number` +
      `&id=in.(${candParam})`
    );
    candidatesById = new Map((candRows || []).map((c) => [c.id, c]));

    const umbIds = Array.from(new Set((candRows || [])
      .map((c) => c.umbrella_id)
      .filter(Boolean)));
    if (umbIds.length) {
      const umbParam = umbIds.map(encodeURIComponent).join(',');
      const { rows: umbRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/umbrellas` +
        `?select=id,name,bank_name,sort_code,account_number` +
        `&id=in.(${umbParam})`
      );
      umbrellasById = new Map((umbRows || []).map((u) => [u.id, u]));
    }
  }

  const items = (rows || []).map((r) => {
    const cand = candidatesById.get(r.candidate_id);
    const umb  = cand?.umbrella_id ? umbrellasById.get(cand.umbrella_id) : undefined;
    const effective_pay_channel = resolveEffectivePayChannel({
      pay_method: r.pay_method,
      candidate: cand,
      umbrella: umb
    });
    return { ...r, effective_pay_channel };
  });

  return ok({ items });
}

// ------------------------------------------------------
// MARK READY (validate evidence rules before promotion)
// ------------------------------------------------------
// ------------------------------------------------------
// MARK READY (validate rules before promotion; supports
// settings_defaults.hr_validation_required and
// settings_defaults.ts_reference_required)
// ------------------------------------------------------
 async function handleTsfinMarkReady(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return unauthorized('Unauthorized');

  const payload = await parseJSONBody(req);
  if (!payload || !Array.isArray(payload.timesheet_ids) || payload.timesheet_ids.length === 0) {
    return badRequest("timesheet_ids[] required");
  }
  const ids = [...new Set(payload.timesheet_ids)].filter(Boolean);
  if (ids.length === 0) return badRequest("No valid timesheet_ids");

  const idsParam = ids.map(encodeURIComponent).join(',');

  // Load global feature flags from defaults
  // - ts_reference_required: optional global gating for timesheet reference
  let tsRefRequired = false;
  try {
    const { rows: defRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/settings_defaults?id=eq.1&select=ts_reference_required`
    );
    if (defRows && defRows[0] && typeof defRows[0].ts_reference_required === 'boolean') {
      tsRefRequired = defRows[0].ts_reference_required;
    }
  } catch {
    // if settings lookup fails, proceed with default (false)
  }

  // Current/unlocked TSFIN snapshots we might promote
  const { rows: tsfinRows } = await sbFetch(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
      `?select=timesheet_id,processing_status,candidate_id,client_id,pay_method,basis,` +
      `expenses_charge_ex_vat,expenses_evidence_r2_key,mileage_charge_ex_vat,mileage_evidence_r2_key,` +
      `hr_crosscheck_status,hr_crosscheck_issues` +
      `&timesheet_id=in.(${idsParam})` +
      `&is_current=eq.true` +
      `&locked_by_invoice_id=is.null`
  );

  // Build per-client settings map (requires_hr, autoprocess_hr, no_timesheet_required)
  const clientIds = Array.from(new Set((tsfinRows || []).map(r => r.client_id).filter(Boolean)));
  const hrByClientId           = new Map(); // client_id -> requires_hr
  const autoprocessByClientId  = new Map(); // client_id -> autoprocess_hr
  const noTsReqByClientId      = new Map(); // client_id -> no_timesheet_required

  if (clientIds.length) {
    const csParam = clientIds.map(encodeURIComponent).join(',');
    const { rows: csRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/client_settings` +
        `?select=client_id,requires_hr,autoprocess_hr,no_timesheet_required` +
        `&client_id=in.(${csParam})`
    );
    for (const cs of csRows || []) {
      const cid = cs.client_id;
      if (!cid) continue;
      hrByClientId.set(cid, !!cs.requires_hr);
      autoprocessByClientId.set(cid, !!cs.autoprocess_hr);
      noTsReqByClientId.set(cid, !!cs.no_timesheet_required);
    }
  }

  // Determine which timesheets actually need HR validation (existing validation gate)
  const idsNeedingHr = (tsfinRows || [])
    .filter(r => r.client_id && hrByClientId.get(r.client_id))
    .map(r => r.timesheet_id);

  // Latest validation per TS (only for those that need HR)
  const latestById = new Map();
  const OK = new Set(['VALIDATION_OK','OVERRIDDEN']);

  if (idsNeedingHr.length) {
    const valParam = idsNeedingHr.map(encodeURIComponent).join(',');
    const valUrl =
      `${env.SUPABASE_URL}/rest/v1/timesheet_validations` +
      `?select=timesheet_id,status,updated_at` +
      `&timesheet_id=in.(${valParam})` +
      `&order=timesheet_id.asc,updated_at.desc` +
      `&limit=10000`;

    const { rows: allVals } = await sbFetch(env, valUrl);
    for (const v of allVals || []) {
      if (!latestById.has(v.timesheet_id)) latestById.set(v.timesheet_id, v);
    }
  }

  // Timesheet metadata: reference, authorisation, submission mode, evidence, basis
  const tsMetaMap = new Map();
  {
    const { rows: tsRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?select=timesheet_id,reference_number,authorised_at_server,submission_mode,` +
        `r2_nurse_key,r2_auth_key,manual_pdf_r2_key,basis` +
        `&timesheet_id=in.(${idsParam})`
    );
    for (const t of tsRows || []) {
      tsMetaMap.set(t.timesheet_id, t);
    }
  }

  // NEW: Evidence counts via timesheet_evidence (per timesheet)
  const evidenceCountByTsId = new Map();
  if (ids.length) {
    try {
      const evParam = ids.map(encodeURIComponent).join(',');
      const { rows: evRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/timesheet_evidence` +
          `?select=timesheet_id,count=id` +
          `&timesheet_id=in.(${evParam})` +
          `&group=timesheet_id`
      );
      for (const ev of evRows || []) {
        evidenceCountByTsId.set(ev.timesheet_id, Number(ev.count) || 0);
      }
    } catch (e) {
      console.warn('[handleTsfinMarkReady] evidence count lookup failed (non-fatal)', {
        err: e?.message || String(e)
      });
    }
  }

  const eligibleIds = [];
  const blocked     = [];

  // Candidate → umbrella lookups for pay-channel gating
  const candIds = Array.from(new Set((tsfinRows || []).map((r) => r.candidate_id).filter(Boolean)));
  let candidatesById = new Map();
  let umbrellasById  = new Map();

  if (candIds.length) {
    const candParam = candIds.map(encodeURIComponent).join(',');
    const { rows: candRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/candidates` +
        `?select=id,umbrella_id,account_holder,bank_name,sort_code,account_number` +
        `&id=in.(${candParam})`
    );
    candidatesById = new Map((candRows || []).map((c) => [c.id, c]));

    const umbIds = Array.from(new Set((candRows || [])
      .map((c) => c.umbrella_id)
      .filter(Boolean)));
    if (umbIds.length) {
      const umbParam = umbIds.map(encodeURIComponent).join(',');
      const { rows: umbRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/umbrellas` +
          `?select=id,name,bank_name,sort_code,account_number` +
          `&id=in.(${umbParam})`
      );
      umbrellasById = new Map((umbRows || []).map((u) => [u.id, u]));
    }
  }

  for (const id of ids) {
    const row = (tsfinRows || []).find((r) => r.timesheet_id === id);
    if (!row) {
      blocked.push({ id, reason: 'tsfin_missing_or_locked' });
      continue;
    }
    if (row.processing_status !== 'READY_FOR_HR') {
      blocked.push({ id, reason: `bad_status_${row.processing_status}` });
      continue;
    }

    const clientId   = row.client_id || null;
    const requiresHr = !!(clientId && hrByClientId.get(clientId));
    const autoprocessHr = !!(clientId && autoprocessByClientId.get(clientId));
    const noTsReq    = !!(clientId && noTsReqByClientId.get(clientId));

    const tsMeta = tsMetaMap.get(id) || {};

    // 1) HR Validation gating (per client) — existing behaviour
    if (requiresHr) {
      const v = latestById.get(id);
      if (!v || !OK.has(v.status)) {
        blocked.push({ id, reason: 'validation_not_ok' });
        continue;
      }
    }

    // 1b) Authorisation gating when autoprocess_hr = false — existing
    if (requiresHr && !autoprocessHr) {
      const authorised = !!tsMeta.authorised_at_server;
      if (!authorised) {
        blocked.push({ id, reason: 'awaiting_team_authorisation' });
        continue;
      }
    }

    // NEW 1c) HR cross-check gate
    if (requiresHr) {
      const hrStatus = (row.hr_crosscheck_status || '').toString().toUpperCase() || null;
      const hrIssues = Array.isArray(row.hr_crosscheck_issues) ? row.hr_crosscheck_issues : [];

      if (hrStatus && hrStatus !== 'OK') {
        // e.g. HOURS_MISMATCH_HR or HR_HOURS_MISSING
        blocked.push({ id, reason: 'hr_crosscheck_failed' });
        continue;
      }

      if (hrIssues.includes('DUPLICATE_CONTRACTS')) {
        // Even if status is OK, duplicates should block promotion
        blocked.push({ id, reason: 'hr_crosscheck_failed' });
        continue;
      }
    }

    // 1d) Timesheet required gate (no_timesheet_required=false) + evidence
    if (requiresHr && !noTsReq) {
      const basisStr = String(tsMeta.basis || row.basis || '').toUpperCase();
      const subMode  = String(tsMeta.submission_mode || '').toUpperCase();

      const isHrBasis =
        basisStr.startsWith('HEALTHROSTER') ||
        basisStr.startsWith('NHSP') ||
        basisStr === 'SELF_REPORTED';

      const hasElectronic =
        subMode === 'ELECTRONIC' &&
        !!(tsMeta.r2_nurse_key && tsMeta.r2_auth_key);

      const hasManual = !!tsMeta.manual_pdf_r2_key;

      const evCount = evidenceCountByTsId.get(id) || 0;
      const hasAnyEvidence = (evCount > 0) || hasManual || hasElectronic;

      if (isHrBasis && !hasAnyEvidence) {
        blocked.push({ id, reason: 'timesheet_missing' });
        continue;
      }
    }

    // 2) Evidence rules: if charge>0 → expenses/mileage evidence required
    const expChg = Number(row.expenses_charge_ex_vat || 0);
    const milChg = Number(row.mileage_charge_ex_vat || 0);
    if (expChg > 0 && !row.expenses_evidence_r2_key) {
      blocked.push({ id, reason: 'expenses_evidence_missing' });
      continue;
    }
    if (milChg > 0 && !row.mileage_evidence_r2_key) {
      blocked.push({ id, reason: 'mileage_evidence_missing' });
      continue;
    }

    // 3) Pay-channel gating
    const cand = candidatesById.get(row.candidate_id);
    const umb  = cand?.umbrella_id ? umbrellasById.get(cand.umbrella_id) : undefined;
    const channel = resolveEffectivePayChannel({
      pay_method: row.pay_method,  // prefer TSFIN snapshot
      candidate: cand,
      umbrella: umb
    });
    if (!channel.ok) {
      blocked.push({ id, reason: 'pay_channel_missing' });
      continue;
    }

    // 4) Timesheet reference gating (if required)
    if (tsRefRequired) {
      const meta = tsMetaMap.get(id);
      const ref = (meta?.reference_number || '').toString().trim();
      if (!ref) {
        blocked.push({ id, reason: 'reference_missing' });
        continue;
      }
    }

    // Passed all gates
    eligibleIds.push(id);
  }

  if (!eligibleIds.length) {
    return badRequest("No timesheets are eligible to mark READY_FOR_INVOICE (validation/evidence/pay-channel/reference/timesheet/authorisation/HR rules failed).");
  }

  // Promote READY_FOR_HR → READY_FOR_INVOICE for just the eligible set
  const updUrl =
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
    `?timesheet_id=in.(${eligibleIds.map(encodeURIComponent).join(',')})` +
    `&is_current=eq.true` +
    `&locked_by_invoice_id=is.null` +
    `&processing_status=eq.READY_FOR_HR`;

  const res = await fetch(updUrl, {
    method: "PATCH",
    headers: { ...sbHeaders(env), "Prefer": "return=representation" },
    body: JSON.stringify({
      processing_status: "READY_FOR_INVOICE",
      updated_at: new Date().toISOString()
    })
  });

  if (!res.ok) {
    const t = await res.text();
    return serverError(`Failed to mark READY_FOR_INVOICE: ${t}`);
  }

  const promoted = await res.json().catch(() => []);
  return ok({
    promoted_count: promoted.length,
    promoted_ids: promoted.map((r) => r.timesheet_id),
    blocked_ids: blocked
  });
}


